from itertools import permutations

def solve_pairing(n):
    """
    Checks if a valid pairing exists for a given n.
    Returns True and the pairing if successful, False otherwise.
    """
    numbers = list(range(1, 2 * n + 1))
    required_diffs = set(range(1, n + 1))

    # We will use a recursive backtracking approach

    def backtrack(remaining_numbers, remaining_diffs, current_pairs):
        if not remaining_numbers:
            if not remaining_diffs:
                return current_pairs
            return None # Should not happen if initial setup is correct

        if not remaining_diffs and remaining_numbers:
            return None # Cannot pair remaining numbers if all diffs are used

        # Choose the smallest remaining number to start a new pair
        start_num = min(remaining_numbers)

        # Try pairing start_num with any other remaining number
        for i in range(len(remaining_numbers)):
            partner_num = remaining_numbers[i]

            if partner_num == start_num:
                continue

            diff = abs(start_num - partner_num)

            if diff in remaining_diffs:

                # Found a potential pair (start_num, partner_num)

                new_remaining_numbers = [x for x in remaining_numbers if x != start_num and x != partner_num]
                new_remaining_diffs = remaining_diffs - {diff}
                new_current_pairs = current_pairs + [(min(start_num, partner_num), max(start_num, partner_num))]

                result = backtrack(new_remaining_numbers, new_remaining_diffs, new_current_pairs)

                if result is not None:
                    return result

        return None

    result = backtrack(numbers, required_diffs, [])

    if result:
        return True, result
    else:
        return False, None

# Test cases n=1 to n=5
test_values = [1, 2, 3, 4, 5]
results = {}
for n in test_values:
    success, pairing = solve_pairing(n)
    results[n] = {'success': success, 'pairing': pairing}

for n, res in results.items():
    print(f"n={n}: Success={res['success']}")
    if res['success']:
        print(f"  Pairing: {res['pairing']}")
    else:
        print(f"  Reason: Fails.")

